const S_DAYS=[['Day 1',1,4],['Day 2',5,11],['Day 3',12,17],['Day 4',18,27],['Weeks later',28,28],['February',29,31]];
function sFit(ed,VW,VH){ const aw=ed.fmt.w-92, ah=ed.fmt.h-172, k=Math.min(aw/VW,ah/VH); return `width="${Math.round(VW*k)}" height="${Math.round(VH*k)}"`; }
function sMark(book,n,x,y,r){ const v=book.voices[book.ch[n-1][1]];
  return v==='The Signal'?`<rect x="${x-r}" y="${y-r}" width="${2*r}" height="${2*r}" fill="var(--ac)"/>`:v==='Dissolution'?`<circle cx="${x}" cy="${y}" r="${r-.6}" fill="var(--bg)" stroke="var(--ink)" stroke-width="1.2"/>`:`<circle cx="${x}" cy="${y}" r="${r}" fill="var(--ink)"/>`; }
function sGrid(ed,book,cols,top,cell,draw,aria){ // rows = chapters, cols = [[id,label,group?]]
  const LW=126, RH=13, n=book.ch.length, VW=LW+cols.length*cell+22, VH=top+n*RH+6, Y=i=>top+i*RH+RH/2, X=j=>LW+j*cell+cell/2;
  let s=`<svg viewBox="0 0 ${VW} ${VH}" ${sFit(ed,VW,VH)} role="img" aria-label="${aria}" font-family="var(--hf)" fill="var(--ink)">`;
  S_DAYS.forEach(([l,a,b],i)=>{ const y0=top+(a-1)*RH, h=(b-a+1)*RH; if(i%2===0) s+=`<rect x="0" y="${y0}" width="${VW}" height="${h}" fill="var(--ink)" fill-opacity=".06"/>`;
    if(h>=30) s+=`<text transform="translate(10,${y0+h/2}) rotate(-90)" text-anchor="middle" font-size="7.5" letter-spacing=".08em" opacity=".7">${l.toUpperCase()}</text>`; });
  cols.forEach((c,j)=>{ s+=`<line x1="${X(j)}" x2="${X(j)}" y1="${top}" y2="${VH-6}" stroke="var(--ink)" stroke-opacity=".12"/><text transform="translate(${X(j)+3},${top-5}) rotate(-60)" font-size="9">${c[1]}</text>`; });
  for(let i=0;i<n;i++){ s+=sMark(book,i+1,26,Y(i),4.2)+`<text x="35" y="${Y(i)+3.2}" font-size="9"><tspan opacity=".6">${i+1}</tspan> ${esc(book.ch[i][0])}</text>`; }
  s+=draw(X,Y); return s+'</svg>'; }
function placeSVG(ed,book){ const cols=S_LANES, J=Object.fromEntries(cols.map((c,j)=>[c[0],j]));
  return sGrid(ed,book,cols,84,14,(X,Y)=>{ let d='',s='';
    S_CH.forEach((c,i)=>{ const x=X(J[c[0]]),y=Y(i); if(!i) d=`M${x},${y}`; else { const px=X(J[S_CH[i-1][0]]),py=Y(i-1),my=(py+y)/2; d+=` C${px},${my} ${x},${my} ${x},${y}`; } });
    s+=`<path d="${d}" fill="none" stroke="var(--ac)" stroke-width="1.6" stroke-opacity=".85"/>`;
    let g=null; cols.forEach((c,j)=>{ if(c[2]!==g&&j){ s+=`<line x1="${X(j)-8}" x2="${X(j)-8}" y1="30" y2="${Y(S_CH.length-1)+7}" stroke="var(--ink)" stroke-opacity=".35" stroke-dasharray="1 3"/>`; } g=c[2]; });
    S_CH.forEach((c,i)=>{ s+=sMark(book,i+1,X(J[c[0]]),Y(i),4.4); }); return s; },'Where each chapter happens'); }
function presenceSVG(ed,book){ const cols=[...S_PEOPLE,...S_THREADS,['obj','The objects']], P=S_PEOPLE.length, T=Object.fromEntries(S_THREADS.map((t,j)=>[t[0],P+j])), O=cols.length-1;
  return sGrid(ed,book,cols,84,14,(X,Y)=>{ let s=`<line x1="${X(P)-7}" x2="${X(P)-7}" y1="30" y2="${Y(S_CH.length-1)+7}" stroke="var(--ink)" stroke-opacity=".4"/><line x1="${X(O)-7}" x2="${X(O)-7}" y1="30" y2="${Y(S_CH.length-1)+7}" stroke="var(--ink)" stroke-opacity=".4"/>`;
    S_CH.forEach((c,i)=>{ const y=Y(i);
      S_PEOPLE.forEach(([id],j)=>{ if(c[1].includes(id)) s+=`<rect x="${X(j)-5}" y="${y-4}" width="10" height="8" rx="1" fill="var(--ink)"/>`; else if(c[2].includes(id)) s+=`<rect x="${X(j)-4.5}" y="${y-3.5}" width="9" height="7" rx="1" fill="none" stroke="var(--ink)" stroke-width="1" stroke-dasharray="2 1.5"/>`; });
      c[3].forEach(t=>{ s+=`<circle cx="${X(T[t])}" cy="${y}" r="2.6" fill="var(--ac)"/>`; });
      if(S_OBJ[i+1]) s+=`<rect x="${X(O)-4}" y="${y-4}" width="8" height="8" transform="rotate(45 ${X(O)} ${y})" fill="var(--ink)"/>`; else if(S_ECHO[i+1]) s+=`<rect x="${X(O)-2.6}" y="${y-2.6}" width="5.2" height="5.2" transform="rotate(45 ${X(O)} ${y})" fill="none" stroke="var(--ink)"/>`; });
    return s; },'Who is present and which threads recur in each chapter'); }
function boothSVG(ed,book){ const VW=300,VH=470,t=w=>marfaTime(w).min, n=book.ch.length;
  const T=book.ch.map(c=>t(c[4])), t0=Math.floor(T[0]/30)*30, t1=Math.ceil(T[n-1]/30)*30, A=58,B=196,y0=30,y1=VH-16, by=v=>y0+(v-t0)/(t1-t0)*(y1-y0);
  const gap=12, rows=n, unit=(y1-y0-gap*(S_DAYS.length-1))/rows, sy=[]; let y=y0; S_DAYS.forEach(([l,a,b])=>{ for(let k=a;k<=b;k++){ sy[k-1]=y+unit/2; y+=unit; } y+=gap; });
  let s=`<svg viewBox="0 0 ${VW} ${VH}" ${sFit(ed,VW,VH)} role="img" aria-label="Recording time at the booth against time in the story" font-family="var(--hf)" fill="var(--ink)">`;
  s+=`<text x="${A}" y="14" text-anchor="middle" font-size="9" letter-spacing=".1em" opacity=".75">AT THE BOOTH</text><text x="${B}" y="14" text-anchor="middle" font-size="9" letter-spacing=".1em" opacity=".75">IN THE STORY</text>`;
  s+=`<line x1="${A}" x2="${A}" y1="${y0}" y2="${y1}" stroke="var(--ink)" stroke-opacity=".5"/>`;
  for(let v=t0;v<=t1;v+=30){ s+=`<line x1="${A-4}" x2="${A}" y1="${by(v)}" y2="${by(v)}" stroke="var(--ink)"/><text x="${A-8}" y="${by(v)+3}" text-anchor="end" font-size="9">${String(v/60|0).padStart(2,'0')}:${String(v%60).padStart(2,'0')}</text>`; }
  y=y0; S_DAYS.forEach(([l,a,b])=>{ const h=(b-a+1)*unit; s+=`<rect x="${B-6}" y="${y}" width="12" height="${h}" fill="var(--ink)" fill-opacity=".09"/><text x="${B+14}" y="${y+Math.min(h/2,14)+3}" font-size="9.5">${l}</text>`; y+=h+gap; });
  for(let i=0;i<n;i++) s+=`<path d="M${A},${by(T[i])} C${(A+B)/2},${by(T[i])} ${(A+B)/2},${sy[i]} ${B},${sy[i]}" fill="none" stroke="var(--ink)" stroke-opacity=".38" stroke-width=".8"/>`;
  for(let i=0;i<n;i++) s+=sMark(book,i+1,A,by(T[i]),3)+sMark(book,i+1,B,sy[i],3);
  s+=`<text x="${A+8}" y="${y1+4}" font-size="8.5" opacity=".7">${Math.floor((T[n-1]-T[0])/60)} h ${(T[n-1]-T[0])%60} min, Marfa time (${marfaTime(book.ch[0][4]).tz})</text>`;
  return s+'</svg>'; }
const SKEY=`<p class="mk"><span><i class="k p"></i>The Pilgrim</span><span><i class="k s"></i>The Signal</span><span><i class="k d"></i>Dissolution</span></p>`;
function storyHTML(ed,book){
  return `<article class="pg fm map" data-page="iii"><div class="mo"></div><div class="mp"><h2>Place, presence, threads</h2><p class="ml">Where each chapter happens, read downward.</p>${placeSVG(ed,book)}${SKEY}</div><footer class="fo"><span>One line, thirty-one stops</span><span>iii</span></footer></article>`+
  `<article class="pg fm map" data-page="iv"><div class="mo"></div><div class="mp"><h2>Place, presence, threads</h2><p class="ml">Who is in the room, and what carries from one chapter to the next.</p>${presenceSVG(ed,book)}<p class="mk"><span><i class="pp"></i>On scene</span><span><i class="pp r"></i>At a distance</span><span><i class="pt"></i>Thread</span><span><i class="po"></i>Object</span></p></div><footer class="fo"><span>Recurring people and things</span><span>iv</span></footer></article>`; }
function boothHTML(ed,book){ return `<article class="pg fm map" data-page="vii"><div class="mo"></div><div class="mp"><h2>Booth time vs. story time</h2><p class="ml">The chapters were recorded in one afternoon at the booth and told in that order.</p>${boothSVG(ed,book)}${SKEY}</div><footer class="fo"><span>Token timestamps from the booth</span><span>vii</span></footer></article>`; }

const ROMAN=['i','ii','iii','iv','v','vi','vii','viii','ix','x','xi','xii','xiii','xiv','xv'];
const arts=h=>h.split('</article>').filter(x=>x.trim()).map(x=>x+'</article>');
function frontHTML(ed,book){
  const intro=(book.intro||'').trim(), introBody=intro?intro.split(/\n\s*\n/).map(t=>/^[—–-]/.test(t.trim())?`<p class="sig">${esc(t.trim())}</p>`:`<p>${esc(t.trim())}</p>`).join(''):`<p class="tbc">Text to come.</p>`;
  const st=arts(storyHTML(ed,book)), mp=arts(mapsHTML(ed,book));
  const P=[
   ['title',`<article class="pg fm title" data-page="i"><div class="mo"></div><div class="tp"><h1>Desert<br>Syntax</h1><p class="sub">a collaborative performance score<br>Marfa, Texas, ${book.date}</p><p class="ed">Edition ${ed.id}</p></div></article>`],
   ['contents',null],
   ['intro',`<article class="pg fm prelude" data-page="i"><div class="mo"></div><div class="in"><h2>High Altitude</h2>${introBody}</div><footer class="fo"><span></span><span>i</span></footer></article>`,'High Altitude'],
   ['place',st[0],'Place, presence, threads'],['presence',st[1]],['region',mp[0],'Where it happened'],['town',mp[1],'Marfa'],['booth',arts(boothHTML(ed,book))[0],'Booth time vs. story time'],
   ['blank',`<article class="pg fm blank" data-page="i" aria-label="Blank page"></article>`]];
  const num=(h,r,k)=>h.replace(/data-page="[^"]*"/,`data-page="${r}" id="fm-${k}"`).replace(/<span>[ivx]+<\/span><\/footer>/,`<span>${r}</span></footer>`);
  const entry=(k,label,r)=>`<li><a class="xl" href="#${k}"><span>${label}</span><i></i><em>${r}</em></a></li>`;
  let rows='';P.forEach(([k,h,label],i)=>{ if(label) rows+=entry('fm-'+k,label,ROMAN[i]); });
  const chs=book.ch.map((c,i)=>`<li><a class="xl" href="#ch-${i+1}"><em>${i+1}</em><span>${esc(c[0])}</span></a></li>`).join('');
  P[1][1]=`<article class="pg fm contents" data-page="i"><div class="mo"></div><div class="cn"><h2>Contents</h2><ol>${rows}</ol><h3>The chapters</h3><ol class="cw">${chs}</ol><ol>${entry('fm-colophon','Colophon','')}</ol></div><footer class="fo"><span></span><span>i</span></footer></article>`;
  return `<article class="pg fm cover" data-page="cover" aria-label="Cover">${coverSVG(ed)}</article>`+P.map(([k,h],i)=>num(h,ROMAN[i],k)).join('');
}
function backHTML(ed,book){
  const pseed=parseInt(ed.seed.slice(-8),16)%99999, ptime=['dawn','morning','noon','afternoon','dusk','overcast'][parseInt(ed.seed.slice(-10,-8),16)%6];
  return `<article class="pg fm plant" data-page="drawing" aria-label="Drawing of a prickly pear"><div class="mo"></div><div class="pw"><canvas class="pl" data-seed="${pseed}" data-time="${ptime}"></canvas></div><footer class="fo"><span>Prickly pear, ${ptime}, no. ${pseed}</span><span></span></footer></article><article class="pg fm colo" data-page="end" id="fm-colophon"><div class="mo"></div><div class="cp"><h2>Colophon</h2><dl><dt>Edition</dt><dd>${ed.id}</dd><dt>Seed</dt><dd class="sd">${ed.seed}</dd><dt>Cover word</dt><dd>${esc(ed.word)}</dd><dt>Palette</dt><dd>${ed.pal.n}</dd><dt>Type</dt><dd>${ed.type.n}</dd><dt>Grammar</dt><dd>${ed.grammar.join(' + ')}</dd><dt>Motif</dt><dd>${ed.motif}</dd><dt>Text</dt><dd>${book.ch.length} tokens on Base</dd><dd class="sd">${book.contract}</dd></dl></div></article>`;
}
const FAM={cabin:"'DS Cabin',sans-serif",bodoni:"'DS Bodoni',serif",plex:"'DS Plex',monospace"};
function bookCSSVars(ed){ const P=ed.pal,T=ed.type,F=ed.fmt;
  return `--w:${F.w}px;--h:${F.h}px;--bg:${P.bg};--ink:${P.ink};--ac:${P.ac};--se:${P.se};--hf:${FAM[T.h]};--bf:${FAM[T.b]};--hw:${T.hw};--hi:${T.hi?'italic':'normal'};--hc:${T.hc?'uppercase':'none'};--hs:${T.hs}em;--lh:${T.lh};--fs:${T.fs}px;--al:${ed.align};`; }

/* the introduction flows over as many pages as it needs; then the front matter is renumbered
   and a blank page is added when needed so that chapter 1 always opens on a right-hand page */
function paginateIntro(el){
  const first=el.querySelector('.pg.prelude'); if(!first) return; const orig=first.querySelector('.in').innerHTML;
  for(const k of [1,.96,.92]){ el.querySelectorAll('.pg.prelude.more').forEach(p=>p.remove()); first.querySelector('.in').innerHTML=orig; el.querySelectorAll('.pg.prelude').forEach(p=>p.style.setProperty('--fsk',k));
    flowIntro(el,first,k); const last=[...el.querySelectorAll('.pg.prelude')].pop(), box=last.querySelector('.in');
    if(last===first || box.getBoundingClientRect().height>last.getBoundingClientRect().height*.3) break; }
}
function flowIntro(el,pg,k){
  const limit=p=>p.querySelector('.fo').getBoundingClientRect().top-8, over=p=>{ const box=p.querySelector('.in'), l=box.lastElementChild; return l&&l.getBoundingClientRect().bottom>limit(p); };
  for(let guard=0; guard<8 && over(pg); guard++){
    const nx=document.createElement('article'); nx.className='pg fm prelude more'; nx.innerHTML='<div class="mo"></div><div class="in"></div><footer class="fo"><span></span><span>i</span></footer>'; nx.style.setProperty('--fsk',k);
    pg.after(nx); const src=pg.querySelector('.in'), dst=nx.querySelector('.in');
    while(over(pg) && src.children.length>1) dst.prepend(src.lastElementChild);
    // split the first moved paragraph at a line boundary: the lines that fit stay, the rest carry over
    const first=dst.firstElementChild;
    if(first && first.tagName==='P' && !first.classList.contains('sig')){
      const words=first.textContent.split(' '), part=document.createElement('p'); part.className='split';
      part.innerHTML=words.map(w=>`<span>${esc(w)}</span>`).join(' '); src.appendChild(part);
      const L=limit(pg), sp=[...part.children]; let cut=sp.findIndex(x=>x.getBoundingClientRect().bottom>L);
      if(cut<0) cut=sp.length;
      if(words.length-cut<4 && cut<words.length){ const top=sp[cut-1]&&sp[cut-1].getBoundingClientRect().top; while(cut>0 && sp[cut-1].getBoundingClientRect().top>=top-1) cut--; }
      if(cut<4){ part.remove(); } else { part.textContent=words.slice(0,cut).join(' '); first.textContent=words.slice(cut).join(' '); first.classList.add('carry'); if(!first.textContent) first.remove(); }
    }
    pg=nx; }
}
function renumberFront(el){
  const all=[...el.querySelectorAll('.pg')], c1=all.findIndex(p=>p.id==='ch-1'); if(c1<0) return;
  all.slice(1,c1).filter(p=>p.classList.contains('blank')).forEach(p=>p.remove());
  const now=[...el.querySelectorAll('.pg')]; let front=now.slice(1,now.findIndex(p=>p.id==='ch-1'));
  if(front.length%2===0){ const b=document.createElement('article'); b.className='pg fm blank'; b.setAttribute('aria-label','Blank page'); el.querySelector('#ch-1').before(b); front.push(b); }
  front.forEach((p,i)=>{ const r=ROMAN[i]; p.dataset.page=r; const sp=p.querySelectorAll('.fo span'); if(sp.length>1) sp[sp.length-1].textContent=r; });
  el.querySelectorAll('.cn a.xl[href^="#fm-"]').forEach(a=>{ const t=el.querySelector(a.getAttribute('href')), em=a.querySelector('em'); if(t&&em&&t.classList.contains('fm')&&front.includes(t)) em.textContent=t.dataset.page; });
}

function renderBook(el,ed,book,DV,opts){
  ed.at=termIndex(book); const pages=plan(ed,book); let html=frontHTML(ed,book);
  pages.forEach((p,i)=>html+=pageHTML(ed,p,pages.length,i+1)); html+=backHTML(ed,book);
  el.className='book t-'+ed.type.n+' f-'+ed.fmt.n; el.setAttribute('style',bookCSSVars(ed)); el.innerHTML=html;
  el.querySelectorAll('canvas.vg').forEach(c=>{ const S=3,cw=120,ch=cw*.75; c.width=cw*S;c.height=ch*S;
    if(DV) DV.draw(c.getContext('2d'),c.dataset.id,{variant:+c.dataset.v,seed:ed.seed,ink:ed.pal.ink,paper:ed.pal.bg,w:cw*S,h:ch*S,background:false,weight:1.1}); });
  el.querySelectorAll('canvas.pl').forEach(c=>{ const F=ed.fmt, cw=F.w-92, ch=Math.min(Math.round(cw*1.22),F.h-130), S=3; c.style.width=cw+'px'; c.style.height=ch+'px'; c.width=cw*S; c.height=ch*S;
    if(root.DesertPlant2D) root.DesertPlant2D.draw(c.getContext('2d'),{seed:+c.dataset.seed,time:c.dataset.time,w:cw*S,h:ch*S,ink:ed.pal.ink,paper:ed.pal.bg,accent:ed.pal.ac}); });
  paginateIntro(el); renumberFront(el); fit(el); return pages;
}
function bottom(pg){ let m=0; pg.querySelectorAll('.tx,.bt,.ob,.vg,.hd,.wd,aside').forEach(n=>{ if(n.offsetParent!==null) m=Math.max(m,n.getBoundingClientRect().bottom); }); return m; }
function fit(el){ el.querySelectorAll('.pg:not(.fm)').forEach(pg=>{ const fo=pg.querySelector('.fo'), over=()=>bottom(pg)>fo.getBoundingClientRect().top-6; let k=1;
  const step=min=>{ while(k>min&&over()){ k=+(k-.01).toFixed(2); pg.style.setProperty('--fit',k); } };
  step(.93); if(over()){ const v=pg.querySelector('canvas.vg'); if(v){ v.style.width='92px'; v.style.height='69px'; } } step(.88); if(over()){ const v=pg.querySelector('canvas.vg'); if(v){ v.style.width='72px'; v.style.height='54px'; } } step(.86); if(over()){ pg.style.setProperty('--big',Math.floor(parseFloat(pg.style.getPropertyValue('--big'))*.68)+'px'); pg.style.setProperty('--foot',Math.floor(parseFloat(pg.style.getPropertyValue('--foot'))*.68)+'px'); } step(.78); pg.dataset.fit=k.toFixed(2); pg.dataset.over=over()?'1':''; }); }
